#include <ccd/ccd.h>
ced_t ccd;
CCD_INIT(&ccd);
ccd.support1 = support;
ccd.support2 = support;
ccd.max_iterations = 100;
int intersect = ccdGJKIntersect(obj1, obj2, &ccd);

std::shared_ptr<BVHModel<OBBRSSf>> geom = std::make_shared<BVHModel<OBBRSSf>>();
geom->beginModel();
geom->addSubModel(vertices, triangles);
geom->endModel();
CollisionObjectf* obj = new CollisionObjectf(geom, pose);
CollisionRequest request; CollisionResult result;
collide(o1, o2, request, result);

collision_detection::CollisionRequest req;
collision_detection::CollisionResult res;
req.group_name = "manipulator";
planning_scene.checkCollision(req, res, robot_state, acm);
bool collides = res.collision;

physx::PxFoundation* foundation = PxCreateFoundation(PX_PHYSICS_VERSION, allocator, errorCallback);
physx::PxPhysics* physics = PxCreateBasePhysics(PX_PHYSICS_VERSION, *foundation, scale);
physx::PxScene* scene = physics->createScene(sceneDesc);
sceneDesc.flags |= physx::PxSceneFlag::eENABLE_PCM;
scene->simulate(dt);

b2WorldId world = b2CreateWorld(&worldDef);
b2BodyDef bodyDef = b2_defaultBodyDef;
bodyDef.type = b2_dynamicBody;
b2BodyId body = b2CreateBody(world, &bodyDef);
b2PolygonShapeDef shapeDef = b2_defaultPolygonShapeDef;
b2CreatePolygonShape(body, &shapeDef, &polygon);
b2World_Step(world, timeStep, subStepCount);

#include "gpu_voxels/GpuVoxels.h"
using namespace gpu_voxels;
GpuVoxelsPtr gpu_voxels = GpuVoxels::getInstance();
gpu_voxels->initialize(200, 200, 200, 0.01);
gpu_voxels->addRobot("robot", "package://robot_description/urdf/robot.urdf", std::vector<std::string>(), true);
gpu_voxels->updateRobot("robot", robot_joint_positions);
gpu_voxels->insertPointcloud("env_cloud", pointcloud_data, eBVM_OCCUPIED);
bool collision = gpu_voxels->collide("robot_bitvector", "env_cloud_bitvector");
std::vector<Vector3i> colliding_voxels = gpu_voxels->getCollidingVoxels("robot", "env_cloud");

#include <octomap/octomap.h>
octomap::OcTree tree(0.05);
tree.insertPointCloud(cloud, sensor_origin);
